{
  "extractions": [
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "The purpose of 8 FAM 801.2 is to provide guidance regarding the use of information request letters (IRLs) and information notices (INs).",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "IRLs are personalized, standardized letters with a date and signature block that request from the applicant additional information, documentation, or action needed to process the passport application.",
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "You must fully adjudicate the passport application prior to suspending to ensure that you are addressing all issues.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "The IRLs have been carefully crafted to communicate clearly and accurately statutory, regulatory, and other requirements of the Department.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "Passport agencies/centers must not make unilateral changes or alterations to the IRLs without the approval of the Office of Adjudication (CA/PPT/S/A), except on a case-by-case basis with the approval of passport agency/center management in extenuating circumstances (e.g., when you request that the applicant submit a birth certificate instead of a notification of birth registration, and the applicant insists that the notification of birth registration is the birth certificate).",
        "kind": "prohibition",
        "modality": "must_not",
        "modality_quote": "must not",
        "references": [
          "CA/PPT/S/A"
        ]
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "Posts must use the cleared language in the IRLs, but are authorized to modify the language to suit local logistical requirements and other local concerns such as available documentation.",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "Posts are authorized to modify the cleared language in the IRLs to suit local logistical requirements and other local concerns such as available documentation.",
        "kind": "authority",
        "modality": "may",
        "modality_quote": "authorized"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "IRLs are not adjudicative guidance.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "The passport application must be adjudicated in accordance with the 8 FAM and then the appropriate IRL selected to address any deficiencies with the passport or Consular Report of Birth Abroad (CRBA).",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must",
        "references": [
          "8 FAM"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "INs are standardized notices that provide passport bearers with information about their passports (for example, an IN may be included to explain why the passport was limited in validity, and/or what documentation is needed to obtain a fully valid passport).",
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "The INs have been carefully crafted to communicate information about their passports clearly and accurately.",
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "No changes or alterations to the INs may be made unilaterally at passport agencies/centers without the approval of CA/PPT/S/A, except in extenuating circumstances on a case-by-case basis with the approval of passport agency/center management (e.g., when using an endorsement 46 to limit a passport for a special problem).",
        "kind": "prohibition",
        "modality": "must_not",
        "modality_quote": "no changes or alterations to the INs may be made",
        "references": [
          "CA/PPT/S/A"
        ]
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "INs do not require a response from the applicant and do not need to be personalized with the applicant's name and address.",
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "do not require"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "statement": "When tailoring correspondence to a situation, Posts may consult Passport Services’ IRL index and IN Index or contact AskPPTAdjudication@state.gov.",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may"
      }
    }
  ]
}
